@push('styles')<style>.product-create{max-width:1100px;margin:auto;padding:28px}.product-create>header{display:flex;justify-content:space-between;align-items:end;margin-bottom:22px}.product-create header h1{margin:4px 0}.product-create header span{font-size:11px;color:#6541d8;font-weight:800}.product-create header p{color:#667085;margin:0}.product-create header a{padding:10px 13px;background:#fff;border:1px solid #e5e7eb;border-radius:11px}.create-card{background:#fff;border:1px solid #e5e7eb;border-radius:22px;padding:22px;margin-bottom:16px}.card-title h2{margin:0;font-size:18px}.card-title p{font-size:12px;color:#667085}.dropzone{border:1.5px dashed #c9c3e8;background:#faf9ff;border-radius:18px;padding:35px;text-align:center;display:grid;gap:7px;place-items:center;color:#6541d8}.dropzone strong{color:#222;font-size:15px}.dropzone small{color:#667085}.pickers{display:flex;gap:9px;margin-top:10px}.pickers label{background:#6541d8;color:#fff;padding:10px 14px;border-radius:10px;cursor:pointer;font-size:12px}.pickers input{display:none}.file-list{display:grid;gap:8px;margin-top:12px}.file-item{display:flex;align-items:center;justify-content:space-between;padding:11px 13px;border:1px solid #edf0f4;border-radius:12px}.file-item span{font-size:12px}.file-item small{color:#667085}.fields{display:grid;grid-template-columns:repeat(2,1fr);gap:14px}.create-card label{display:block;font-size:12px;font-weight:800;margin-top:13px}.create-card label input,.create-card label select,.create-card label textarea{display:block;width:100%;margin-top:6px;padding:11px;border:1px solid #dfe3ea;border-radius:11px;font:inherit;box-sizing:border-box}.create-card textarea{resize:vertical}.submit-row{display:flex;justify-content:space-between;align-items:center;background:#111827;color:#fff;border-radius:18px;padding:17px 20px}.submit-row strong,.submit-row span{display:block}.submit-row span{font-size:11px;color:#c7cad1;margin-top:3px}.submit-row button{border:0;background:#fff;color:#111827;border-radius:11px;padding:11px 17px;font:inherit;font-weight:900;cursor:pointer}.alert-error{background:#fff0f0;color:#a33;border-radius:12px;padding:12px;margin-bottom:14px}@media(max-width:700px){.product-create{padding:15px}.product-create>header,.submit-row{display:block}.product-create header a{display:inline-block;margin-top:12px}.fields{grid-template-columns:1fr}.pickers{flex-direction:column}.pickers label{width:100%;box-sizing:border-box}}</style>@endpush
@push('scripts')<script>(function(){const input=document.getElementById('fileInput'),folder=document.getElementById('folderInput'),zone=document.getElementById('dropzone'),list=document.getElementById('fileList'),form=document.getElementById('productForm');let uploaded=[];function files(fs){Array.from(fs||[]).forEach(upload)}async function upload(file){const fd=new FormData();fd.append('_token','{{ csrf_token() }}');fd.append('file',file);const row=document.createElement('div');row.className='file-item';row.innerHTML='<span>'+file.name+'</span><small>در حال بررسی...</small>';list.appendChild(row);try{const r=await fetch('{{ route('admin.products.uploads.store') }}',{method:'POST',body:fd,headers:{Accept:'application/json'}});const d=await r.json();if(!r.ok)throw new Error(d.message||'آپلود ناموفق بود');(d.files||[]).forEach(f=>{uploaded.push(f.id);row.querySelector('small').textContent='آماده ثبت';});}catch(e){row.querySelector('small').textContent=e.message;row.style.borderColor='#e99'}}input?.addEventListener('change',e=>files(e.target.files));folder?.addEventListener('change',e=>files(e.target.files));['dragenter','dragover'].forEach(x=>zone?.addEventListener(x,e=>{e.preventDefault();zone.classList.add('over')}));zone?.addEventListener('dragleave',()=>zone.classList.remove('over'));zone?.addEventListener('drop',e=>{e.preventDefault();zone.classList.remove('over');files(e.dataTransfer.files)});form?.addEventListener('submit',e=>{if(!uploaded.length){e.preventDefault();alert('حداقل یک فایل محصول انتخاب کنید.');return}uploaded.forEach(id=>{const i=document.createElement('input');i.type='hidden';i.name='upload_ids[]';i.value=id;form.appendChild(i)})})})();</script>@endpush
